 phrase(kind,key){let h=0;for(const ch of key)h=(Math.imul(h,31)+ch.charCodeAt(0))>>>0;return this.phrases[kind][h%this.phrases[kind].length];},
 add(a,kind,id,node=null,place=null){const e=S.events.find(e=>e.id===a.event);if(!e||Qualifiers.isRegional(e)||!S.teams[id]||a.withdrawnV12&&id===S.club)return;const key=e.id+':'+kind+':'+(kind==='series'?node.id+':':'')+id,m=this.store();if(m.posts.some(p=>p.id===key))return;const pair=node?.pair.map(v=>resolve6(a,v)),side=pair?.indexOf(id),score=node?.score?node.score.split(':').map(Number):null;const ranked=a.entrants.filter(t=>a.placements[t]===place).length,slots=a.schedule.filter(n=>n.outPlace===place).length,count=Math.max(ranked,slots,1);m.posts.push({id:key,kind,event:e.id,eventName:e.name,day:S.day,to:ClubNews60A.club(S.teams[id]),from:null,palette:ClubNews60A.palette(S.teams[id]),caption:this.phrase(kind,key),score:score&&side>=0?(side===0?score:score.reverse()).join(' : '):null,opponent:pair&&side>=0?ClubNews60A.club(S.teams[pair[1-side]]):null,place:place==null?null:count>1?place+'–'+(place+count-1):String(place),photos:roster(S.teams[id]).map(p=>({id:p.id,name:p.name,photo:photo20(p)||null})),trophy:Trophy4B.select(e).key});
 if(kind==='champions'&&id===S.club&&m.month.key===this.key())m.month.titles.push({event:e.id,name:e.name,score:m.posts.at(-1).score,trophy:m.posts.at(-1).trophy,pool:e.pool||0});},
